"use client"

import {
  Alert02Icon,
  AudioWave01Icon,
  Brain01Icon,
  CheckmarkCircle02Icon,
  Exchange01Icon,
  HourglassIcon,
  HourglassOffIcon,
  InformationCircleIcon,
  Mic01Icon,
  VolumeHighIcon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/shared/icon"

/* The four sections of the Model Settings tab, told apart by their glyph. */
export const LanguageModelIcon = icon(Brain01Icon, "LanguageModelIcon")
export const SpeechToTextIcon = icon(Mic01Icon, "SpeechToTextIcon")
export const TextToSpeechIcon = icon(VolumeHighIcon, "TextToSpeechIcon")
export const TurnDetectionIcon = icon(HourglassIcon, "TurnDetectionIcon")

/* The detection path that ran, and the case where it was not the configured one. */
export const DetectionPathIcon = icon(AudioWave01Icon, "DetectionPathIcon")
export const FellBackIcon = icon(Exchange01Icon, "FellBackIcon")

/* Whether the wait behaved: every turn inside the window, or some at the ceiling. */
export const WithinWindowIcon = icon(CheckmarkCircle02Icon, "WithinWindowIcon")
export const ReachedMaximumIcon = icon(Alert02Icon, "ReachedMaximumIcon")

/* A call from before turn timing was recorded has nothing to read. */
export const NotRecordedIcon = icon(HourglassOffIcon, "NotRecordedIcon")

/**
 * What a reading means, on hover rather than printed under it.
 *
 * The circled "i", matching the platform's own hover-help at
 * `components/scenario/tools/form-components/tooltip-help.tsx`.
 */
export const FieldHelpIcon = icon(InformationCircleIcon, "FieldHelpIcon")

"use client"

import { Separator } from "@/components/ui/separator"
import {
  MODEL_SETTINGS,
  type CallCase,
  type TurnTimingRecord,
} from "@/lib/mockups/call-turn-timing-data"

import { LanguageModelIcon, SpeechToTextIcon, TextToSpeechIcon } from "./icons"
import { TurnDetectionSection } from "./turn-detection-section"

/**
 * The Model Settings tab of the call detail, with the new turn detection
 * section in place.
 *
 * The three sections below it are unchanged and are here only so the placement
 * reads: turn detection goes first because it is the only one that reports what
 * happened rather than echoing what was configured, and it is what someone
 * opens this tab to find when a client says the agent was slow.
 */
export function ModelSettingsTab({
  timing,
  voice,
}: {
  timing: null | TurnTimingRecord
  voice: CallCase["voice"]
}) {
  return (
    <div className="flex flex-col gap-6">
      <TurnDetectionSection timing={timing} />

      <Separator />

      <ConfigSection
        icon={<LanguageModelIcon />}
        title="Language Model"
        rows={[
          { label: "Provider", value: MODEL_SETTINGS.llm.provider },
          { label: "Model", value: MODEL_SETTINGS.llm.model },
        ]}
      />

      <Separator />

      <ConfigSection
        icon={<SpeechToTextIcon />}
        title="Speech-to-Text"
        rows={[
          { label: "Provider", value: MODEL_SETTINGS.stt.provider },
          { label: "Model", value: MODEL_SETTINGS.stt.model },
        ]}
      />

      <Separator />

      <ConfigSection
        icon={<TextToSpeechIcon />}
        title="Text-to-Speech"
        rows={[
          { label: "Provider", value: MODEL_SETTINGS.tts.provider },
          { label: "Model", value: MODEL_SETTINGS.tts.model },
          { label: "Voice", value: voice.name },
          { label: "Language", value: voice.language },
          { label: "Gender", value: voice.gender },
        ]}
      />
    </div>
  )
}

/** The label-and-value shape the tab already uses for every model section. */
function ConfigSection({
  icon,
  title,
  rows,
}: {
  icon: React.ReactNode
  title: string
  rows: { label: string; value: string }[]
}) {
  return (
    <section className="flex flex-col gap-3">
      <h3 className="flex items-center gap-2 text-base font-medium">
        {icon}
        {title}
      </h3>
      <div className="flex flex-col gap-3">
        {rows.map((row) => (
          <div
            key={row.label}
            className="flex items-start justify-between gap-4 text-sm"
          >
            <span>{row.label}</span>
            <span className="text-end">{row.value}</span>
          </div>
        ))}
      </div>
    </section>
  )
}

"use client"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty"
import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemGroup,
  ItemMedia,
  ItemTitle,
} from "@/components/ui/item"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import {
  RECOMMENDED_MAX_WAIT_CEILING_SECONDS,
  formatSeconds,
  type TurnTimingRecord,
} from "@/lib/mockups/call-turn-timing-data"

import {
  DetectionPathIcon,
  FellBackIcon,
  FieldHelpIcon,
  NotRecordedIcon,
  ReachedMaximumIcon,
  TurnDetectionIcon,
  WithinWindowIcon,
} from "./icons"

/**
 * The section this ticket adds to a call's Model Settings tab.
 *
 * It answers the one question the tab cannot answer today — why this call was
 * paced the way it was — so it leads the tab rather than trailing the config
 * echoes below it. Three blocks, in the order a pacing complaint gets read:
 * which path ran, what window it was given, and what the caller actually sat
 * through.
 */
export function TurnDetectionSection({
  timing,
}: {
  /** `null` for a call placed before turn timing was recorded. */
  timing: null | TurnTimingRecord
}) {
  return (
    <section className="flex flex-col gap-4">
      <div className="flex items-center justify-between gap-4">
        <h3 className="flex items-center gap-2 text-base font-medium">
          <TurnDetectionIcon />
          Turn detection
        </h3>
        {timing ? <OutcomeBadge timing={timing} /> : null}
      </div>

      {timing ? <RecordedTiming timing={timing} /> : <NotRecorded />}
    </section>
  )
}

function RecordedTiming({ timing }: { timing: TurnTimingRecord }) {
  const fellBack = timing.fallbackReason !== null
  const firstTurnReachedMaximum =
    timing.firstTurnWaitSeconds >= timing.maxWaitSeconds

  return (
    <div className="flex flex-col gap-6">
      <Block
        title="Path that ran"
        help="Chosen in Global Settings. The agent falls back when the configured path cannot start, and the call continues either way."
      >
        <ItemGroup className="gap-2">
          {fellBack ? (
            <Item variant="outline">
              <ItemMedia variant="icon">
                <DetectionPathIcon className="text-muted-foreground" />
              </ItemMedia>
              <ItemContent>
                <ItemTitle className="text-muted-foreground">
                  {timing.configured.label}
                </ItemTitle>
                <ItemDescription>
                  {timing.configured.description}
                </ItemDescription>
              </ItemContent>
              <ItemActions className="self-start">
                <Badge variant="outline">Configured</Badge>
              </ItemActions>
            </Item>
          ) : null}

          <Item variant="outline">
            <ItemMedia variant="icon">
              {fellBack ? <FellBackIcon /> : <DetectionPathIcon />}
            </ItemMedia>
            <ItemContent>
              <ItemTitle>{timing.ran.label}</ItemTitle>
              <ItemDescription>{timing.ran.description}</ItemDescription>
            </ItemContent>
            <ItemActions className="self-start">
              <Badge variant={fellBack ? "destructive" : "secondary"}>
                {fellBack ? "Ran instead" : "Configured and ran"}
              </Badge>
            </ItemActions>
          </Item>
        </ItemGroup>

        {timing.fallbackReason ? (
          <Alert variant="destructive">
            <FellBackIcon />
            <AlertTitle>
              {timing.configured.label} did not run on this call
            </AlertTitle>
            <AlertDescription>
              {timing.fallbackReason} The wait values below are the ones the
              fallback applied, not the ones configured for{" "}
              {timing.configured.label}.
            </AlertDescription>
          </Alert>
        ) : null}
      </Block>

      <Block
        title="Wait window that applied"
        help="Read once at call start. A settings change since then has not affected this call."
        action={
          <Badge variant="secondary">
            {timing.waitSource === "persona"
              ? `Persona override · ${timing.persona}`
              : `Global default · ${timing.persona} inherits`}
          </Badge>
        }
      >
        <div className="grid gap-4 md:grid-cols-2">
          <Stat
            label="Minimum wait"
            value={formatSeconds(timing.minWaitSeconds)}
            caption="Applied on every confident turn."
            help="How long the agent held off once the model was confident the caller had finished."
          />
          <Stat
            label="Maximum wait"
            value={formatSeconds(timing.maxWaitSeconds)}
            caption={
              timing.maxWaitSeconds > RECOMMENDED_MAX_WAIT_CEILING_SECONDS
                ? "Above the recommended ceiling, so an unsure model left callers waiting longer."
                : "Inside the recommended band."
            }
            help="The ceiling the agent waited out whenever the model could not decide."
          />
        </div>
      </Block>

      <Block
        title="What the caller sat through"
        help="Recorded per turn, independent of the detection model — a path that failed to start is still measured."
      >
        <div className="grid gap-4 md:grid-cols-2">
          <Stat
            label="Turns at the maximum"
            value={`${timing.turnsAtMaximum} of ${timing.turnCount}`}
            caption={
              timing.turnsAtMaximum === 0
                ? "Every turn resolved before the ceiling."
                : "The model never reached confidence on these, so the full maximum applied."
            }
            tone={timing.turnsAtMaximum === 0 ? "default" : "warning"}
          />
          <Stat
            label="First turn"
            value={formatSeconds(timing.firstTurnWaitSeconds)}
            caption={
              firstTurnReachedMaximum
                ? "Reached the maximum. This is the first thing the caller experienced."
                : "Resolved inside the window."
            }
            tone={firstTurnReachedMaximum ? "warning" : "default"}
          />
        </div>

        {firstTurnReachedMaximum ? (
          <Alert>
            <ReachedMaximumIcon className="text-warning" />
            <AlertTitle>
              The opening turn waited the full{" "}
              {formatSeconds(timing.maxWaitSeconds)}
            </AlertTitle>
            <AlertDescription>
              Lowering the maximum wait on {timing.persona} shortens this
              silence, at the cost of interrupting callers who pause
              mid-sentence.
            </AlertDescription>
          </Alert>
        ) : null}
      </Block>
    </div>
  )
}

/** A call from before turn timing was recorded shows nothing rather than today's settings. */
function NotRecorded() {
  return (
    <Empty className="rounded-lg border">
      <EmptyHeader>
        <EmptyMedia variant="icon">
          <NotRecordedIcon />
        </EmptyMedia>
        <EmptyTitle>Turn timing was not recorded</EmptyTitle>
        <EmptyDescription>
          This call was placed before the detection path and wait values were
          captured. The settings in effect now are not necessarily the ones this
          call ran with, so they are not shown here.
        </EmptyDescription>
      </EmptyHeader>
    </Empty>
  )
}

/** The one-word verdict, so the section can be triaged from the collapsed tab. */
function OutcomeBadge({ timing }: { timing: TurnTimingRecord }) {
  if (timing.fallbackReason !== null) {
    return <Badge variant="destructive">Fell back</Badge>
  }

  if (timing.turnsAtMaximum > 0) {
    return (
      <Badge className="bg-warning/15 text-warning-foreground">
        <ReachedMaximumIcon />
        Reached the maximum
      </Badge>
    )
  }

  return (
    <Badge variant="secondary">
      <WithinWindowIcon />
      Within the window
    </Badge>
  )
}

/**
 * A block of the panel.
 *
 * `help` replaced what used to be a `description` printed under every title.
 * The split that survived review: a sentence that *defines* how the platform
 * works is read once and belongs on the (i); a sentence that *reads this call*
 * is the content and stays on the surface. Three definitions came off this
 * panel that way.
 */
function Block({
  title,
  help,
  action,
  children,
}: {
  title: string
  help: string
  action?: React.ReactNode
  children: React.ReactNode
}) {
  return (
    <div className="flex flex-col gap-3">
      <div className="flex items-center justify-between gap-4">
        <div className="flex items-center gap-1">
          <span className="text-sm font-medium">{title}</span>
          <HelpDot label={`What "${title}" means`}>{help}</HelpDot>
        </div>
        {action ? <div className="shrink-0">{action}</div> : null}
      </div>
      {children}
    </div>
  )
}

function HelpDot({
  children,
  label,
}: {
  children: React.ReactNode
  label: string
}) {
  return (
    <Tooltip>
      <TooltipTrigger
        aria-label={label}
        className="cursor-help text-muted-foreground"
      >
        <FieldHelpIcon className="size-4" />
      </TooltipTrigger>
      <TooltipContent className="max-w-64">{children}</TooltipContent>
    </Tooltip>
  )
}

/**
 * One reading. `caption` is this call's verdict and stays visible; `help` is
 * the metric's definition and goes on the (i).
 */
function Stat({
  label,
  value,
  caption,
  help,
  tone = "default",
}: {
  label: string
  value: string
  caption: string
  help?: string
  tone?: "default" | "warning"
}) {
  return (
    <div className="flex flex-col gap-1 rounded-lg bg-muted p-4">
      <span className="flex items-center gap-1 text-sm text-muted-foreground">
        {label}
        {help ? (
          <HelpDot label={`What "${label}" measures`}>{help}</HelpDot>
        ) : null}
      </span>
      <span
        className={
          tone === "warning"
            ? "text-xl font-semibold text-warning-foreground"
            : "text-xl font-semibold"
        }
      >
        {value}
      </span>
      <p className="text-sm text-muted-foreground">{caption}</p>
    </div>
  )
}

"use client"

import {
  ArrowDown01Icon,
  BlockGameIcon,
  BookOpen02Icon,
  BubbleChatIcon,
  Building02Icon,
  CallRinging04Icon,
  Chart03Icon,
  ChartColumnIcon,
  CodeIcon,
  DashboardBrowsingIcon,
  DashboardCircleIcon,
  Globe02Icon,
  GoogleDocIcon,
  Key01Icon,
  Message02Icon,
  PlayIcon,
  PlusSignIcon,
  Queue02Icon,
  RoboticIcon,
  Settings01Icon,
  ShieldKeyIcon,
  SmartPhone01Icon,
  CpuIcon,
  TaskDaily01Icon,
  TelephoneIcon,
  VariableIcon,
  VoiceIcon,
  WebhookIcon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/shared/icon"

/**
 * Icons for the shared product shell — one glyph per nav destination, matched
 * to the app's own sidebar. Icons *inside* a mockup live in that mockup's own
 * icons.tsx; this file is only the app chrome.
 */
export const PlaygroundIcon = icon(PlayIcon, "PlaygroundIcon")
export const PersonasIcon = icon(RoboticIcon, "PersonasIcon")
export const ScenariosIcon = icon(GoogleDocIcon, "ScenariosIcon")
export const KnowledgeIcon = icon(BookOpen02Icon, "KnowledgeIcon")
export const BatchCallsIcon = icon(Queue02Icon, "BatchCallsIcon")
export const TemplateIcon = icon(DashboardCircleIcon, "TemplateIcon")
export const GlobalPromptsIcon = icon(Globe02Icon, "GlobalPromptsIcon")
export const VoiceLibraryIcon = icon(VoiceIcon, "VoiceLibraryIcon")
export const DashboardIcon = icon(Chart03Icon, "DashboardIcon")
export const ConversationsIcon = icon(CallRinging04Icon, "ConversationsIcon")
export const MessagingIcon = icon(Message02Icon, "MessagingIcon")
export const QualityIcon = icon(DashboardBrowsingIcon, "QualityIcon")
export const ReportsIcon = icon(ChartColumnIcon, "ReportsIcon")
export const TasksIcon = icon(TaskDaily01Icon, "TasksIcon")
export const KeyIcon = icon(Key01Icon, "KeyIcon")
export const VariablesIcon = icon(VariableIcon, "VariablesIcon")
export const WebhooksIcon = icon(WebhookIcon, "WebhooksIcon")
export const IntegrationsIcon = icon(BlockGameIcon, "IntegrationsIcon")
export const DeveloperDocsIcon = icon(CodeIcon, "DeveloperDocsIcon")
export const BuildingIcon = icon(Building02Icon, "BuildingIcon")
export const RolesIcon = icon(ShieldKeyIcon, "RolesIcon")
export const MobileIcon = icon(SmartPhone01Icon, "MobileIcon")
/* The model catalog (DES-169), under Configuration. */
export const ModelsIcon = icon(CpuIcon, "ModelsIcon")
export const TelephonyIcon = icon(TelephoneIcon, "TelephonyIcon")
export const SettingsIcon = icon(Settings01Icon, "SettingsIcon")
export const MessagingSettingsIcon = icon(
  BubbleChatIcon,
  "MessagingSettingsIcon",
)
export const ChevronDownIcon = icon(ArrowDown01Icon, "ChevronDownIcon")
/** The hover "+" on Personas and Scenarios — creates one without leaving the nav. */
export const NewItemIcon = icon(PlusSignIcon, "NewItemIcon")

"use client"

import Image from "next/image"
import * as React from "react"

import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb"
import { Button } from "@/components/ui/button"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import { Separator } from "@/components/ui/separator"
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuAction,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarTrigger,
  useSidebar,
} from "@/components/ui/sidebar"
import { cn } from "@/lib/utils"
import {
  BatchCallsIcon,
  BuildingIcon,
  ChevronDownIcon,
  ConversationsIcon,
  DashboardIcon,
  DeveloperDocsIcon,
  GlobalPromptsIcon,
  IntegrationsIcon,
  KeyIcon,
  KnowledgeIcon,
  MessagingIcon,
  MessagingSettingsIcon,
  MobileIcon,
  ModelsIcon,
  NewItemIcon,
  PersonasIcon,
  PlaygroundIcon,
  QualityIcon,
  ReportsIcon,
  RolesIcon,
  ScenariosIcon,
  SettingsIcon,
  TasksIcon,
  TelephonyIcon,
  TemplateIcon,
  VariablesIcon,
  VoiceLibraryIcon,
  WebhooksIcon,
} from "@/components/shell/app-shell-icons"

/**
 * The app around any mockup screen, shared by every mockup that wants the
 * product chrome: an inset sidebar over a tinted page, and a header carrying
 * the breadcrumb and the account. Pass `active` to highlight the nav item the
 * screen lives under.
 *
 * Playground sits above the groups rather than inside one — it is the entry
 * point, not a build step. Configuration starts closed because it is the group
 * you visit once and then leave alone.
 */

interface NavItem {
  /** Label for the hover "+", on the two things you create most. */
  action?: string
  icon: React.ComponentType
  title: string
}

const PLAYGROUND: NavItem = { icon: PlaygroundIcon, title: "Playground" }

const NAV: { defaultOpen: boolean; items: NavItem[]; label: string }[] = [
  {
    defaultOpen: true,
    label: "Agents",
    items: [
      { action: "New persona", icon: PersonasIcon, title: "Personas" },
      { action: "New scenario", icon: ScenariosIcon, title: "Scenarios" },
      { icon: KnowledgeIcon, title: "Knowledge Bases" },
      { icon: BatchCallsIcon, title: "Batch Calls" },
      { icon: TemplateIcon, title: "Scenario Templates" },
      { icon: GlobalPromptsIcon, title: "Global Prompts" },
      { icon: VoiceLibraryIcon, title: "Voice Library" },
    ],
  },
  {
    defaultOpen: true,
    label: "Monitor",
    items: [
      { icon: DashboardIcon, title: "Dashboard" },
      { icon: ConversationsIcon, title: "Conversations" },
      { icon: MessagingIcon, title: "Messaging" },
      { icon: QualityIcon, title: "Quality Dashboard" },
      { icon: ReportsIcon, title: "Reports" },
      { icon: TasksIcon, title: "Tasks" },
    ],
  },
  {
    defaultOpen: false,
    label: "Configuration",
    items: [
      { icon: KeyIcon, title: "API Keys" },
      { icon: VariablesIcon, title: "Variables" },
      { icon: WebhooksIcon, title: "Webhooks" },
      { icon: IntegrationsIcon, title: "Integrations" },
      { icon: DeveloperDocsIcon, title: "Developer Docs" },
      { icon: BuildingIcon, title: "Organizations" },
      /* DES-170. Roles are platform-wide and Sarj-only in Phase 1, so they sit
         beside Organizations rather than inside one. */
      { icon: RolesIcon, title: "Roles" },
      { icon: MobileIcon, title: "Phone Numbers" },
      /* DES-169. The catalog needs a home in the nav, and Configuration is
         where the other platform-wide, Sarj-staff-only surfaces already sit. */
      { icon: ModelsIcon, title: "Models" },
      { icon: TelephonyIcon, title: "Telephony" },
      { icon: SettingsIcon, title: "Global Settings" },
      { icon: MessagingSettingsIcon, title: "Messaging Settings" },
    ],
  },
]

function NavLink({
  active,
  item,
  onNavigate,
}: {
  active: boolean
  item: NavItem
  onNavigate?: (title: string) => void
}) {
  return (
    <SidebarMenuItem>
      <SidebarMenuButton
        /* Two differences from the primitive's defaults, both as the app has
           them: hover lands on the neutral `accent` rather than the purple
           `sidebar-accent`, and the active item carries a hairline of its own
           foreground so the filled pill reads as a border, not just a wash. */
        className="border border-transparent hover:bg-accent hover:text-accent-foreground data-active:border-sidebar-accent-foreground/10"
        isActive={active}
        tooltip={item.title}
        onClick={() => onNavigate?.(item.title)}
      >
        <item.icon />
        {/* Closing to the rail fades the label out rather than clipping it. */}
        <span className="truncate transition-opacity duration-200 ease-out-cubic group-data-[collapsible=icon]:opacity-0 motion-reduce:transition-none">
          {item.title}
        </span>
      </SidebarMenuButton>
      {/* `rounded-sm` in place of the primitive's `rounded-md` and `right-2` in
          place of `right-1`, both as the app has them.

          The glyph size is deliberately NOT the app's `[&>svg]:size-full`. That
          class works there because its plus is a hand-drawn 20×20 icon whose
          path spans only 6.5→13.5, so filling the box still draws a 7px plus.
          Ours is HugeIcons' PlusSignIcon, whose ink fills 16 of its 24 viewBox
          units — the same class drew a 12px plus, nearly twice the app's.
          `size-2.5` renders it at 10px, putting the drawn plus at 6.7px. */}
      {item.action ? (
        <SidebarMenuAction
          aria-label={item.action}
          className="top-1.5 right-2 rounded-sm border border-input bg-background text-muted-foreground hover:bg-accent hover:text-foreground [&>svg]:size-2.5"
        >
          <NewItemIcon />
        </SidebarMenuAction>
      ) : null}
    </SidebarMenuItem>
  )
}

/**
 * Collapsed to the icon rail there is no room for a section label, so the
 * groups are forced open and the label — the only thing that could close them —
 * is disabled.
 */
function NavGroup({
  active,
  defaultOpen,
  items,
  label,
  onNavigate,
}: {
  active: string
  defaultOpen: boolean
  items: NavItem[]
  label: string
  onNavigate?: (title: string) => void
}) {
  const { state } = useSidebar()
  const isCollapsed = state === "collapsed"
  const [open, setOpen] = React.useState(defaultOpen)

  return (
    <Collapsible
      disabled={isCollapsed}
      onOpenChange={isCollapsed ? undefined : setOpen}
      open={isCollapsed || open}
    >
      <SidebarGroup>
        <SidebarGroupLabel asChild>
          <CollapsibleTrigger className="flex w-full cursor-pointer items-center justify-between hover:bg-accent/50">
            <span>{label}</span>
            <ChevronDownIcon
              className={cn(
                "transition-transform duration-200 ease-out-cubic motion-reduce:transition-none",
                open ? "rotate-0" : "-rotate-90",
              )}
            />
          </CollapsibleTrigger>
        </SidebarGroupLabel>
        <CollapsibleContent>
          <SidebarGroupContent>
            <SidebarMenu>
              {items.map((item) => (
                <NavLink
                  active={item.title === active}
                  item={item}
                  key={item.title}
                  onNavigate={onNavigate}
                />
              ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </CollapsibleContent>
      </SidebarGroup>
    </Collapsible>
  )
}

/** Breadcrumb start, account end — the row every page in the app sits under. */
export function AppHeader({
  actions,
  trail,
  showSettings,
}: {
  /** Replaces the account row entirely. The design-system page uses it to
   *  carry the way back to the index; a mockup leaves it off and gets the
   *  row the app itself shows. */
  actions?: React.ReactNode
  /** Crumbs after Home. The last is the page; earlier ones are links. */
  trail: readonly string[]
  showSettings?: boolean
}) {
  return (
    <header className="flex h-16 shrink-0 items-center justify-between gap-4 px-4">
      <Breadcrumb>
        {/* The app spaces its crumbs at 2.5; the primitive ships 1.5. */}
        <BreadcrumbList className="gap-2.5">
          <BreadcrumbItem>
            <BreadcrumbLink href="#">Home</BreadcrumbLink>
          </BreadcrumbItem>
          {trail.map((crumb, index) => (
            <React.Fragment key={crumb}>
              <BreadcrumbSeparator />
              <BreadcrumbItem>
                {index === trail.length - 1 ? (
                  <BreadcrumbPage>{crumb}</BreadcrumbPage>
                ) : (
                  <BreadcrumbLink href="#">{crumb}</BreadcrumbLink>
                )}
              </BreadcrumbItem>
            </React.Fragment>
          ))}
        </BreadcrumbList>
      </Breadcrumb>

      <div className="flex shrink-0 items-center gap-2">
        {actions ?? (
          <>
            <Button size="sm" variant="outline">
              <DeveloperDocsIcon />
              Developer Doc
            </Button>
            {/* The same allowlist the nav reads. The app has this gear on its own
            check today, which is how an admin gets a second dead end to the
            page the sidebar already sent them to. */}
            {showSettings ? (
              <Button
                aria-label="Global settings"
                size="icon-sm"
                variant="outline"
              >
                <SettingsIcon />
              </Button>
            ) : null}
            {/* Wrapped, rather than given `self-center`: the primitive ships
            `data-vertical:self-stretch`, and an attribute variant outranks a
            plain utility, so the rule stretched to the 28px row, got held to
            h-4, and settled at the top of it — 6px above the centre the buttons
            and the avatar share. Inside a wrapper of its own the flex line is
            the rule's own height, so stretching changes nothing and the wrapper
            is what the header centres. */}
            <div className="flex items-center">
              <Separator className="mx-1 h-4" orientation="vertical" />
            </div>
            {/* A rounded square at the same radius and height as the two buttons,
            not a circle. The app's account button is Clerk's, and Clerk does not
            inherit the app's CSS vars — so the real header sets its avatar
            radius to a 0.625rem literal, which is `--radius`, which is
            `rounded-lg`. A circle here is the one thing in this row that would
            not be in the app. `after:` and the fallback carry the primitive's
            own `rounded-full`, so both have to be squared off with it. */}
            <Avatar className="size-7 rounded-lg after:rounded-lg">
              <AvatarFallback className="rounded-lg">TA</AvatarFallback>
            </Avatar>
          </>
        )}
      </div>
    </header>
  )
}

export function AppShell({
  active,
  breadcrumb,
  hiddenItems,
  onNavigate,
  children,
}: {
  /** Title of the sidebar item this screen lives under, e.g. "Personas". */
  active: string
  /** Crumbs after Home; a bare string is a single one. Defaults to `active`. */
  breadcrumb?: string | readonly string[]
  /**
   * Nav item titles this viewer's role cannot open, so the menu holds only
   * what they can reach. Omit it and the nav is the full one, which is what
   * every other mockup wants.
   */
  hiddenItems?: readonly string[]
  /** Called with a nav item's title when it is clicked, so a mockup can make
   * the destinations it covers actually switch. Items it ignores stay inert. */
  onNavigate?: (title: string) => void
  children: React.ReactNode
}) {
  const hidden = new Set(hiddenItems ?? [])
  const groups = NAV.map((group) => ({
    ...group,
    items: group.items.filter((item) => !hidden.has(item.title)),
  })).filter((group) => group.items.length > 0)

  return (
    /* The app sizes its sidebar at 15rem; the shadcn primitive ships 16rem.
       Set here rather than in the primitive, which is generated. */
    <SidebarProvider
      className="min-h-0 flex-1"
      style={{ "--sidebar-width": "15rem" } as React.CSSProperties}
    >
      {/* The sidebar pins to the viewport as it does in the app, so it clears
          the mockup shell's own header rather than sliding under it. */}
      <Sidebar className="pt-12" collapsible="icon" variant="inset">
        <SidebarHeader className="px-2 pt-2 pb-1">
          <div className="flex items-center justify-between group-data-[state=collapsed]:justify-center">
            {/* 56×32 is the size the app's own header renders it at. */}
            <Image
              alt="sarj.ai"
              className="group-data-[state=collapsed]:hidden"
              height={32}
              priority
              src="/logo.png"
              width={56}
            />
            <SidebarTrigger className="size-8 rounded-md text-muted-foreground hover:bg-accent hover:text-foreground [&>svg]:size-5" />
          </div>
        </SidebarHeader>

        <SidebarContent>
          <SidebarGroup className="pt-2 pb-0">
            <SidebarGroupContent>
              <SidebarMenu>
                <NavLink
                  active={PLAYGROUND.title === active}
                  item={PLAYGROUND}
                  onNavigate={onNavigate}
                />
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>

          {groups.map((group, index) => (
            <React.Fragment key={group.label}>
              {/* The rail hides section labels, so a rule stands in for the
                  grouping those labels carry when the nav is open. */}
              {index > 0 ? (
                <div className="mx-2 my-1 hidden h-px shrink-0 bg-sidebar-border group-data-[collapsible=icon]:block" />
              ) : null}
              <NavGroup
                active={active}
                /* A closed group hiding the item the screen is on reads as the
                   nav having lost its place, so the active item's group opens
                   regardless of where the group would otherwise start. */
                defaultOpen={
                  group.defaultOpen ||
                  group.items.some((item) => item.title === active)
                }
                items={group.items}
                label={group.label}
                onNavigate={onNavigate}
              />
            </React.Fragment>
          ))}
        </SidebarContent>
      </Sidebar>

      <SidebarInset className="min-w-0 overflow-hidden">
        <AppHeader
          trail={
            breadcrumb === undefined
              ? [active]
              : typeof breadcrumb === "string"
                ? [breadcrumb]
                : breadcrumb
          }
          showSettings={!hidden.has("Global Settings")}
        />
        {/* No gutter here: the page owns its p-3 lg:p-4, matching the header. */}
        <div className="min-h-0 flex-1 overflow-auto">{children}</div>
      </SidebarInset>
    </SidebarProvider>
  )
}

/**
 * The design system, written down.
 *
 * Content only. It lives here rather than inside the page because the rules
 * are a list that gets edited, and a list that gets edited should not be
 * tangled up in the markup that renders it.
 */

/** A named rule and the one line that says what it means. */
export type Rule = {
  label: string
  detail: string
}

/**
 * One of the seven non-negotiables. The `id` picks the worked example that runs
 * underneath it in `RuleDemo` — the rule and its example are one thing, so they
 * are keyed together rather than left to line up by position.
 */
export type GlobalRule = Rule & {
  id:
    | "icons"
    | "shadows"
    | "typography"
    | "spacing"
    | "radius"
    | "accessibility"
    | "scrollbars"
}

/**
 * The non-negotiables. Seven rules, no exceptions, and none of them is a
 * judgement call — which is why they are the first thing on the page.
 */
export const GLOBAL_RULES: GlobalRule[] = [
  {
    id: "icons",
    label: "Icons",
    detail: "Only HugeIcons, at one size and one style across the product.",
  },
  {
    id: "shadows",
    label: "Shadows",
    detail: "One shared set, for elevation or separation. Never decorative.",
  },
  {
    id: "typography",
    label: "Typography",
    detail: "One scale of sizes, weights, line heights and heading styles.",
  },
  {
    id: "spacing",
    label: "Spacing",
    detail: "One scale, and the same rhythm everywhere.",
  },
  { id: "radius", label: "Radius", detail: "A small fixed set of tokens." },
  {
    id: "scrollbars",
    label: "Scrollbars",
    detail:
      "One width and one token, native or ScrollArea. Never an arrow, never a track.",
  },
  {
    id: "accessibility",
    label: "Accessibility",
    detail:
      "Keyboard, visible focus, contrast and labels — part of the pattern, not a later pass.",
  },
]

/** One of the four places a piece of configuration or creation can live. */
export type SurfaceChoice = {
  id: "inline" | "drawer" | "popup" | "multi-step"
  title: string
  /** What this surface is for. */
  criterion: string
  /** What it is never for. The exclusions are the half that gets argued. */
  avoid: string
  examples: string
}

/**
 * The decision the rest of the system hangs off. Two questions, in order: is
 * the reader deciding, or configuring? A decision is a pop-up. Configuration
 * stays inline while it fits beside the value it changes, and becomes a drawer
 * when there is enough of it to crowd the page.
 */
export const SURFACE_CHOICES: SurfaceChoice[] = [
  {
    id: "inline",
    title: "Inline",
    criterion:
      "Changing or configuring something the page is already about, with room for the control where the value sits.",
    avoid: "deciding anything, and creating anything.",
    examples:
      "Agent model, agent instructions, voice selection, project settings.",
  },
  {
    id: "drawer",
    title: "Drawer",
    criterion:
      "Enough to configure, or enough to read, that it would crowd the page — and the page behind it still matters.",
    avoid: "a single quick decision, which does not need a panel.",
    examples: "Agent page → Tools → configure one tool.",
  },
  {
    id: "popup",
    title: "Pop-up",
    criterion:
      "A quick decision, and only that: deleting, confirming, or making something that fits on one screen.",
    avoid: "configuration, and anything with more to read — that is a drawer.",
    examples: "Delete agent, import voice, create API key.",
  },
  {
    /* The fourth surface, and the one that gets skipped: a creation too long
       for a pop-up is usually built as a pop-up anyway, with a scrollbar. It
       is here so the comparison names the point where that stops working. */
    id: "multi-step",
    title: "Multi-step creation",
    criterion:
      "Creating one object that does not fit on one screen, or where a later answer depends on an earlier one.",
    avoid:
      "editing what already exists — a made object is configured inline or in a drawer.",
    examples: "Create voice, connect a telephony endpoint.",
  },
]

